insert into public.games (id, title, tagline, description, genre, engine, config, thumbnail, creator_name, score_per_orb, max_orbs_per_session, daily_orb_cap, max_score_per_second, score_grace, xp_per_play, visits, likes, dislikes, favorites, base_ccu, trend_seed, featured, sort_order, created_at, updated_at) values
  ('orb-rush', 'Orb Rush', 'Dodge, dash and grab every orb.', 'Swipe between three lanes to dodge falling blocks and scoop up glowing orbs. The track speeds up the longer you survive — how far can you go?', 'Action', 'orb_rush', '{"lanes":3,"startSpeed":0.5,"accel":0.012,"maxSpeed":1.6,"spawnEvery":0.85,"orbChance":0.45,"lives":3,"bg":"#120E2E","lane":"#1E1A4A","player":"#22D3EE","block":"#FF4D6D","orb":"#FFC53D"}'::jsonb, '{"from":"#4F46E5","to":"#22D3EE","emblem":"rush","accent":"#FFC53D"}'::jsonb, 'Blockora Studio', 20, 150, 600, 140, 100, 12, 2480000, 41200, 3100, 18900, 1800, 8.5, true, 1, now() - interval '300 days', now() - interval '50 days'),
  ('lava-lanes', 'Lava Lanes', 'The floor is lava. So are the walls.', 'A scorching remix of Orb Rush: faster blocks, rarer orbs and a track that never cools down.', 'Action', 'orb_rush', '{"lanes":3,"startSpeed":0.62,"accel":0.016,"maxSpeed":1.8,"spawnEvery":0.75,"orbChance":0.38,"lives":3,"bg":"#2A0A0A","lane":"#4A1410","player":"#FFD166","block":"#FF7B00","orb":"#FFE066"}'::jsonb, '{"from":"#DC2626","to":"#F59E0B","emblem":"flame","accent":"#FFE066"}'::jsonb, 'Magma Works', 20, 150, 600, 140, 100, 12, 940000, 15400, 1900, 6200, 640, 6.1, false, 2, now() - interval '140 days', now() - interval '23 days'),
  ('neon-highway', 'Neon Highway', 'Race the grid at light speed.', 'Neon lanes, synth skies and an ever-climbing top speed. Chain orb pickups for massive scores.', 'Racing', 'orb_rush', '{"lanes":3,"startSpeed":0.7,"accel":0.02,"maxSpeed":2,"spawnEvery":0.7,"orbChance":0.5,"lives":3,"bg":"#050816","lane":"#0B1437","player":"#39FF14","block":"#F72585","orb":"#4CC9F0"}'::jsonb, '{"from":"#7C3AED","to":"#F72585","emblem":"bolt","accent":"#39FF14"}'::jsonb, 'Synthline', 20, 150, 600, 140, 100, 12, 1320000, 22800, 2100, 9400, 980, 9.2, true, 3, now() - interval '45 days', now() - interval '7 days'),
  ('frost-dash', 'Frost Dash', 'Slide through the glacier gauntlet.', 'A chilly, slightly gentler run through ice caverns — perfect for chasing a long streak.', 'Adventure', 'orb_rush', '{"lanes":3,"startSpeed":0.45,"accel":0.01,"maxSpeed":1.4,"spawnEvery":0.9,"orbChance":0.5,"lives":3,"bg":"#06202F","lane":"#0C3A52","player":"#FFFFFF","block":"#7FDBFF","orb":"#C77DFF"}'::jsonb, '{"from":"#0EA5E9","to":"#E0F2FE","emblem":"snow","accent":"#C77DFF"}'::jsonb, 'Polar Pixel', 20, 150, 600, 140, 100, 12, 610000, 10100, 900, 4100, 310, 3.4, false, 4, now() - interval '210 days', now() - interval '35 days'),
  ('sky-stack', 'Sky Stack', 'Stack higher than the clouds.', 'Tap to drop each sliding block. Overhangs get sliced off — land a perfect drop to keep your tower wide.', 'Casual', 'stacker', '{"startWidth":0.6,"speed":0.9,"speedup":0.035,"perfectTolerance":0.018,"from":"#38BDF8","to":"#1E3A8A","block":"#FDE68A","blockAlt":"#F59E0B"}'::jsonb, '{"from":"#38BDF8","to":"#6366F1","emblem":"stack","accent":"#FDE68A"}'::jsonb, 'Blockora Studio', 1, 60, 400, 8, 10, 10, 1870000, 30500, 2600, 12800, 1250, 7.4, true, 5, now() - interval '280 days', now() - interval '46 days'),
  ('gem-tower', 'Gem Tower', 'Every block is a precious gem.', 'A faster stacker where each layer is a gem. The higher you go, the brighter it shines.', 'Casual', 'stacker', '{"startWidth":0.55,"speed":1.1,"speedup":0.04,"perfectTolerance":0.016,"from":"#581C87","to":"#0F172A","block":"#C084FC","blockAlt":"#22D3EE"}'::jsonb, '{"from":"#9333EA","to":"#0F172A","emblem":"gem","accent":"#22D3EE"}'::jsonb, 'Gemcraft', 1, 60, 400, 8, 10, 10, 720000, 11900, 1300, 4800, 420, 5.2, false, 6, now() - interval '95 days', now() - interval '15 days'),
  ('candy-stacker', 'Candy Stacker', 'Sweet, sticky, surprisingly tricky.', 'Pastel candy layers with a gentle start. Great for warming up — but the pace picks up!', 'Casual', 'stacker', '{"startWidth":0.65,"speed":0.8,"speedup":0.03,"perfectTolerance":0.02,"from":"#FBCFE8","to":"#A78BFA","block":"#FDA4AF","blockAlt":"#93C5FD"}'::jsonb, '{"from":"#F9A8D4","to":"#A78BFA","emblem":"candy","accent":"#FFFFFF"}'::jsonb, 'Sugar Cube Games', 1, 60, 400, 8, 10, 10, 530000, 9800, 700, 3900, 280, 2.8, false, 7, now() - interval '180 days', now() - interval '30 days'),
  ('block-smash', 'Block Smash', '30 seconds. Smash everything.', 'Blocks pop up all over the board — tap them before they vanish. Golden blocks are worth triple, but never tap a bomb!', 'Arcade', 'reflex', '{"duration":30,"spawnEvery":0.55,"lifetime":1.25,"goldenChance":0.1,"bombChance":0.14,"grid":4,"bg":"#0F172A","target":"#22D3EE","golden":"#FFC53D","bomb":"#EF4444"}'::jsonb, '{"from":"#0EA5E9","to":"#6366F1","emblem":"smash","accent":"#FFC53D"}'::jsonb, 'Blockora Studio', 8, 80, 450, 90, 60, 10, 1590000, 26100, 2400, 10200, 1100, 6.9, false, 8, now() - interval '260 days', now() - interval '43 days'),
  ('glow-bugs', 'Glow Bugs', 'Catch the fireflies, skip the wasps.', 'A twilight meadow full of glowing bugs. Quick taps catch fireflies; wasps cost you points.', 'Arcade', 'reflex', '{"duration":30,"spawnEvery":0.5,"lifetime":1.1,"goldenChance":0.12,"bombChance":0.16,"grid":4,"bg":"#052E16","target":"#A3E635","golden":"#FDE047","bomb":"#F97316"}'::jsonb, '{"from":"#166534","to":"#A3E635","emblem":"bug","accent":"#FDE047"}'::jsonb, 'Meadowlight', 8, 80, 450, 90, 60, 10, 460000, 8100, 800, 3100, 230, 4.6, false, 9, now() - interval '60 days', now() - interval '10 days'),
  ('meteor-defense', 'Meteor Defense', 'Protect the station. Tap fast.', 'Meteors streak toward your space station. Blast them before impact — and don''t hit the friendly satellites.', 'Sci-Fi', 'reflex', '{"duration":35,"spawnEvery":0.6,"lifetime":1.3,"goldenChance":0.08,"bombChance":0.12,"grid":4,"bg":"#020617","target":"#F97316","golden":"#FACC15","bomb":"#38BDF8"}'::jsonb, '{"from":"#1E1B4B","to":"#F97316","emblem":"meteor","accent":"#FACC15"}'::jsonb, 'Orbital Arcade', 8, 80, 450, 90, 60, 10, 380000, 6400, 700, 2500, 190, 3.9, false, 10, now() - interval '25 days', now() - interval '4 days'),
  ('glyph-match', 'Glyph Match', 'Flip, remember, match.', 'Find every pair of ancient glyphs before time runs out. Consecutive matches build a combo bonus.', 'Puzzle', 'glyph_match', '{"cols":4,"rows":4,"timeLimit":90,"theme":"glyphs","bg":"#1C1917","card":"#F59E0B","face":"#FFFBEB","accent":"#B45309"}'::jsonb, '{"from":"#B45309","to":"#FDE68A","emblem":"glyph","accent":"#1C1917"}'::jsonb, 'Blockora Studio', 20, 90, 450, 220, 1200, 10, 1210000, 21900, 1500, 9900, 760, 5.8, false, 11, now() - interval '240 days', now() - interval '40 days'),
  ('ocean-pairs', 'Ocean Pairs', 'Dive deep for matching treasures.', 'Shells, fish and sunken treasure hide beneath the waves. A relaxed memory game with a generous timer.', 'Puzzle', 'glyph_match', '{"cols":4,"rows":4,"timeLimit":110,"theme":"ocean","bg":"#082F49","card":"#0EA5E9","face":"#F0F9FF","accent":"#0369A1"}'::jsonb, '{"from":"#0369A1","to":"#5EEAD4","emblem":"wave","accent":"#FFFFFF"}'::jsonb, 'Tidepool', 20, 90, 450, 220, 1200, 10, 410000, 7600, 500, 3300, 170, 2.6, false, 12, now() - interval '150 days', now() - interval '25 days'),
  ('rune-recall', 'Rune Recall', 'Twenty runes. One sharp mind.', 'A bigger 5×4 board of shifting runes and a tight timer. Only true memory masters clear it.', 'Strategy', 'glyph_match', '{"cols":4,"rows":5,"timeLimit":100,"theme":"runes","bg":"#1E1B4B","card":"#6366F1","face":"#EEF2FF","accent":"#4338CA"}'::jsonb, '{"from":"#312E81","to":"#A78BFA","emblem":"rune","accent":"#FDE68A"}'::jsonb, 'Arcane Labs', 20, 90, 450, 220, 1200, 10, 290000, 5900, 600, 2200, 120, 4.1, false, 13, now() - interval '18 days', now() - interval '3 days'),
  ('pixel-pets', 'Pixel Pets', 'Match the cutest critters.', 'Adorable pixel pets are hiding behind the cards. Find every pair and earn a bonus for speed.', 'Puzzle', 'glyph_match', '{"cols":4,"rows":4,"timeLimit":100,"theme":"pets","bg":"#3B0764","card":"#F472B6","face":"#FDF2F8","accent":"#BE185D"}'::jsonb, '{"from":"#DB2777","to":"#FBCFE8","emblem":"paw","accent":"#FFFFFF"}'::jsonb, 'Sugar Cube Games', 20, 90, 450, 220, 1200, 10, 670000, 12900, 800, 5600, 340, 4.4, false, 14, now() - interval '75 days', now() - interval '12 days')
